new NarrativeDefinition("tutorial-tap","Mira",new string[]{"","","","","","",""},new string[]{"Tap the lab or hold down for repeated impulses. One impulse currently grants {TAP} credits.","Tippe auf das Labor oder halte gedrückt für mehrere Impulse. Ein Impuls bringt aktuell {TAP} Credits.","Tap the lab or hold down for repeated impulses. One impulse currently grants {TAP} credits.","Tap the lab or hold down for repeated impulses. One impulse currently grants {TAP} credits.","Tap the lab or hold down for repeated impulses. One impulse currently grants {TAP} credits.","Tap the lab or hold down for repeated impulses. One impulse currently grants {TAP} credits.","Tap the lab or hold down for repeated impulses. One impulse currently grants {TAP} credits."}),
